import{_ as t,l as c,o as a,c as i,v as r,p as s,x as o,d as l,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"memcg","description":"","frontmatter":{"title":"memcg","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memcg.md","filePath":"cs/memcg.md","lastUpdated":1789023840000}'),p={name:"cs/memcg.md"};function h(u,e,g,_,f,E){const m=c("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="memcg" tabindex="-1">memcg <a class="header-anchor" href="#memcg" aria-label="Permalink to &quot;memcg&quot;">​</a></h1><div class="epigraph"><p>memory cgroup 给一组进程一套计数器与上限：匿名、文件、内核、交换；超限则组内回收，再不行 OOM 该组。</p><footer>—— 据 Linux cgroup v2 memory 文档；内核 memcontrol 说明</footer></div><p><a href="/cs/blkio-cgroup">blkio</a> 限 I/O。<a href="/cs/fs-quota">配额</a> 限盘。<a href="/cs/numa-mempolicy">NUMA</a> 限节点。缺口是 <strong>内存控制器</strong>：容器不能吃光主机 DRAM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>v2 <code>memory.max</code>：硬限。<code>memory.high</code>：先回收再可短暂超。记账：页进组，共享页按规则分或记到第一次接触者（实现随版本）。缺口：内核栈、slab、dentry 是否进 <code>memory.stat</code>；OOM killer 选组内任务；与 <a href="/cs/zswap">zswap</a>/swap.max。本课不把 v1 层级与 v2 的每个文件对译完。</p><p><span class="marginnote">writeback 归属：脏文件页的 memcg 必须与 io 节流一致，否则绕过。THP、KSM 使记账粒度变粗或共享。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配：<code>try_charge</code> 该 css，失败则 <code>try_to_free_mem_cgroup_pages</code>（只扫该组 lru）。对照主机回收：全局 LRU vs 组 LRU。对照 <a href="/cs/thin-provisioning">thin</a>：超分配在存储；memcg 是 RAM 硬壁。对照 rmap：回收仍靠反查 pte。</p>',8)),(a(),s(d,null,{default:o(()=>[n(m,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALLOC%5B%22%E5%88%86%E9%85%8D%E9%A1%B5%22%5D%20--%3E%20CHG%5B%22memcg%20charge%22%5D%0A%20%20CHG%20--%3E%7C%22%E8%B6%85%20high%2Fmax%22%7C%20REC%5B%22%E7%BB%84%E5%86%85%E5%9B%9E%E6%94%B6%22%5D%0A%20%20REC%20--%3E%7C%22%E4%BB%8D%E8%B6%85%22%7C%20OOM%5B%22%E7%BB%84%20OOM%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>memcg 把「容器内存隔离」收成内核会计，使多租户可共主机。它不加密内存、不防侧信道。不要写成云账单页。与网络 <a href="/cs/socket-buffers">rmem</a>：套接字内存也可进 memcg（kmem），否则成为逃逸。</p><p>过小的上限导致抖动：不断回收文件页，CPU 打满，看起来像泄漏。</p><p>实现上：kernel memory 记账关闭时，dentry/inode 可被容器用来撑爆宿主。OOM 组选择看 usage 与 oom.group。swap.max 为 0 则回收只能丢文件页。 读法上只引用<a href="/cs/numa-mempolicy">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>memcg</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 PSI 的全部指标解释。不保证 GPU 内存进同一控制器。下一课把缺页交给用户态处理：userfaultfd。</p><p>版本字段会变，课序钉的是机制对象「memcg」，不是某一主线内核的结构体名。 后课默认：组可被 memory.max 挡住并组内 OOM。用户态填页与迁移，下一课 userfaultfd。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>memcg 对组收费并回收/OOM。</li><li>共享页与 writeback 归属是细节陷阱。</li><li>userfaultfd 是下一课。</li><li>出处：cgroup v2 memory；Linux memcontrol；Gorman。</li></ul>',11))])}const x=t(p,[["render",h]]);export{k as __pageData,x as default};
